select DISTINCT B.Account, Debit,Credit, Memo, LineMemo, v.U_NAME + '  Posted Journal Voucher ' from OBTF A INNER JOIN BTF1 B ON A.TransId =B.TransId left join ousr v on b.UserSign=v.USERID WHERE BtfStatus ='O'  and  a.U_CreateTs between cast(Replace(substring(CONVERT(VARCHAR(8), getdate(), 108),1,5),':','') as int)-2 and  cast(Replace(substring(CONVERT(VARCHAR(8), getdate(), 108),1,5),':','') as int) and convert(varchar(10),a.CreateDate ,112)=convert(varchar(10),GETDATE() ,112)
